public class Foo {
    void m(int[] a) {
        for (int i = 0; i < a.length; i++) {
            if (a[i] < 0) {
                i++;
            }
            if (a[i] == 0) {
                i = a.length;
            }
        }
    }
}

public class Foo {
    void m(java.util.List<String> list) {
        for (String s : list) {
            s = s.trim();
            System.out.println(s);
        }
    }
}

public class Foo {
    void m(java.util.List<String> list) {
        for (int i = 0; i < list.size(); i++) {
            System.out.println(list.get(i));
        }
        for (String s : list) {
            String t = s.trim();
            System.out.println(t);
        }
    }
}
